#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 13b: Analytics
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check the preview, then fast forward main.
#
# After this part, Analytics in the sidebar is live (nothing says Soon now):
#   * views and watch time are counted on the shared page, the video page
#     and Presentation Mode: a view after 5 seconds of playing, one per
#     browser tab, the owner's own plays not counted
#   * no cookies and nothing about the viewer is stored: only totals per
#     video per day. The tab's random id lives in that tab and in server
#     memory only; the IP is used in memory only, to cap views per caller
#     (10 per video per day, env VIEWS_PER_CALLER_DAY)
#   * the Analytics page: views, watch time, average view, watched to the
#     end, the change on the period before, views per day, week or month
#     (hover, or Show the numbers), each video's numbers, live events
#     (most viewers at once, chat messages), for 7, 28, 90 days or 12 months
#   * the Privacy Policy describes the counting (effective 14 October 2026)
#   * deleting a video (or Delete my data) deletes its view totals
#
#   BACKEND   3 new files, 3 changed. Migration 018_views (runs by itself)
#   FRONTEND  2 new files, 8 changed. No packages
#
#   ./vm_analytics.sh            apply (needs Part 13a on the branch)
#   ./vm_analytics.sh --force    apply even if local files differ from GitHub
#   ./vm_analytics.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_analytics"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_analytics_backups"

ADD=(
  "backend/src/lib/views.ts"
  "backend/src/lib/analytics.ts"
  "backend/src/routes/analytics.ts"
  "frontend/src/app/analytics/page.tsx"
  "frontend/src/lib/useViewCounter.ts"
)
MOD=(
  "backend/src/index.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/routes/videos.ts"
  "frontend/src/app/legal/privacy/page.tsx"
  "frontend/src/components/legal/LegalPage.tsx"
  "frontend/src/components/layout/AppShell.tsx"
  "frontend/src/components/video/VideoPlayer.tsx"
  "frontend/src/app/v/[id]/page.tsx"
  "frontend/src/app/video/[id]/page.tsx"
  "frontend/src/app/present/[id]/page.tsx"
  "frontend/src/lib/api.ts"
)
