verify "$TMPD/a4" "${NEW_ADD[4]}" "frontend/src/lib/useViewCounter.ts"

grep -q "$MARKER" "$TMPD/a0"                                   || die "views.ts payload missing marker. Aborting."
grep -q 'export async function recordView' "$TMPD/a0"            || die "views.ts payload is wrong. Aborting."
grep -q 'export async function ownerAnalytics' "$TMPD/a1"        || die "lib/analytics.ts payload is wrong. Aborting."
grep -q '/me/analytics' "$TMPD/a2"                               || die "routes/analytics.ts payload is wrong. Aborting."
grep -q 'How views are counted' "$TMPD/a3"                       || die "analytics page payload is wrong. Aborting."
grep -q 'export function useViewCounter' "$TMPD/a4"              || die "useViewCounter.ts payload is wrong. Aborting."
grep -q 'analyticsRouter' "$TMPD/m0"                       || die "index.ts payload missing analytics. Aborting."
grep -q 'settingsRouter' "$TMPD/m0"                        || die "index.ts payload lost settings. Aborting."
grep -q '018_views' "$TMPD/m1"                    || die "migrations.ts payload missing 018. Aborting."
grep -q '017_settings' "$TMPD/m1"                 || die "migrations.ts payload lost 017. Aborting."
grep -q 'deleteViewsForVideo' "$TMPD/m2"           || die "videos.ts payload is wrong. Aborting."
grep -q 'random number for the tab' "$TMPD/m3" || die "privacy page payload is wrong. Aborting."
grep -q '14 October 2026' "$TMPD/m4"  || die "LegalPage.tsx payload is wrong. Aborting."
grep -q 'href: "/analytics"' "$TMPD/m5" || die "AppShell.tsx payload is wrong. Aborting."
grep -q 'countViewsOf' "$TMPD/m6"  || die "VideoPlayer.tsx payload is wrong. Aborting."
grep -q 'countViewsOf' "$TMPD/m7"              || die "shared page payload is wrong. Aborting."
grep -q 'countViewsOf' "$TMPD/m8"          || die "video page payload is wrong. Aborting."
grep -q 'useViewCounter' "$TMPD/m9"      || die "present page payload is wrong. Aborting."
grep -q 'export const getAnalytics' "$TMPD/m10"          || die "api.ts payload is wrong. Aborting."
grep -q 'export const deleteMyData' "$TMPD/m10"          || die "api.ts payload lost settings. Aborting."
say "16 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Analytics (Part 13b)."
say "Nothing to install. Migration 018_views runs when the backend starts."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_analytics.sh --revert"
